class TimelineItem {
  /// Stable across updates of the same item.
  final String uniqueId;
  final TimelineItemKind kind;

  const TimelineItem({required this.uniqueId, required this.kind});

  @override
  int get hashCode => uniqueId.hashCode ^ kind.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is TimelineItem &&
          runtimeType == other.runtimeType &&
          uniqueId == other.uniqueId &&
          kind == other.kind;
}

